# Nginx vhost for set4-upd-php.test
# Written by CelikPanel. Put your own additions in /etc/nginx/celikpanel-sites.d/set4-upd-php.test/*.conf;
# CelikPanel never writes there. If you change this file, CelikPanel keeps
# your file and asks you before it replaces it.
# CelikPanel yazdı. Kendi eklemeleriniz /etc/nginx/celikpanel-sites.d/set4-upd-php.test/*.conf içine;
# CelikPanel oraya hiç yazmaz. Bu dosyayı değiştirirseniz CelikPanel
# dosyanızı korur ve değiştirmeden önce size sorar.
# Site ID: 5 · Project type: php
server {
    listen 80;
    listen [::]:80;
    server_name set4-upd-php.test www.set4-upd-php.test;

    access_log /var/log/nginx/set4-upd-php.test-access.log;
    error_log /var/log/nginx/set4-upd-php.test-error.log;

    # Root-owned validation content only; never tenant public_html.
    location ^~ /.well-known/acme-challenge/ {
        root /var/lib/celikpanel-agent/acme-http-01/subscriptions/2/domains/5;
        try_files $uri =404;
    }

    root /var/www/celikpanel/subscriptions/2/sites/5/public_html;
    index index.php index.html index.htm;

    location / {

        try_files $uri $uri/ /index.php?$query_string;
    }
    location ~ \.php$ {
        fastcgi_split_path_info ^(.+?\.php)(/.*)$;
        try_files $fastcgi_script_name =404;
        set $path_info $fastcgi_path_info;
        fastcgi_param PATH_INFO $path_info;
        fastcgi_index index.php;
        include fastcgi.conf;
        fastcgi_pass unix:/var/run/php/php8.3-fpm-site5.sock;
        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;
        include fastcgi_params;
    }
    location ~ /\.(?!well-known).* {
        deny all;
    }

    # Your additions for this site (server context) / Bu site için eklemeleriniz
    include /etc/nginx/celikpanel-sites.d/set4-upd-php.test/*.conf;
}
